import type { CatalogItemBaseConfig, M2MRelationships, PortalSettings, AvailabilityConfig } from './CatalogItem'
import type { TableName, Table } from '../db'
import type { VariableTypes } from './Variable'
import type { GlideRecord } from '../script/GlideRecord'

/**
 * Context object for Record Producer scripts.
 * Contains variable values and record information.
 */
type RecordProducerContext = {
    /** Access variable values using producer.var_name */
    [key: string]: unknown
}

/**
 * Record Producer definition object passed to scripts.
 */
type RecordProducerDefinition = {
    /** Record Producer configuration and metadata */
    [key: string]: unknown
}
/**
 * Type representing the properties of a Record Producer.
 * A Record Producer extends CatalogItem and adds record creation capabilities.
 */
type CatalogItemRecordProducerConfig<
    T extends TableName,
    V extends VariableTypes = VariableTypes,
> = Now.Internal.WithIdAndMetadata<
    CatalogItemBaseConfig<V> &
        M2MRelationships &
        PortalSettings &
        AvailabilityConfig & {
            /** Whether to allow editing of the generated record after creation
             * @default false
             */
            allowEdit?: boolean

            /** Whether the user can cancel the record producer submission
             * @default false
             */
            canCancel?: boolean

            /** Script executed AFTER the record is generated.
             * Safe to use current.update() here.
             * Use `producer.var_name` to access variables.
             * Use `cat_item` to access the Record Producer definition.
             */
            postInsertScript?:
                | ((producer: RecordProducerContext, current: GlideRecord, cat_item: RecordProducerDefinition) => void)
                | string

            /** Where to redirect after record creation
             * @default 'generatedRecord'
             * Options: 'generatedRecord', 'catalogHomePage'
             */
            redirectUrl?: 'generatedRecord' | 'catalogHomePage'

            /** Options for saving the record producer (advanced configuration) */
            saveOptions?: string

            /** Script executed at every step save in Catalog Builder.
             * Executed BEFORE the main script.
             * Use `current` to access the GlideRecord.
             */
            saveScript?:
                | ((producer: RecordProducerContext, current: GlideRecord, cat_item: RecordProducerDefinition) => void)
                | string

            /** Server-side script executed BEFORE the record is generated.
             * Use `producer.var_name` to access variables.
             * Use `current` to access the GlideRecord being produced.
             * Do NOT use current.update() or current.insert().
             */
            script?: ((producer: RecordProducerContext, current: GlideRecord) => void) | string

            /** Target table name where the record will be created (Required)
             * @example 'incident', 'change_request', 'problem'
             */
            table: T | Table
        }
>

/** @interface */
export type CatalogItemRecordProducer<V extends VariableTypes = VariableTypes> = CatalogItemRecordProducerConfig<
    TableName,
    V
>

/**
 * Creates a Record Producer (`sc_cat_item_producer`) — a catalog item that creates a record in a
 * specified table when submitted. Extends CatalogItem with record creation and script capabilities.
 *
 * @param config Record Producer configuration — target table, variables, fulfillment scripts, and catalog settings.
 * @see https://docs.servicenow.com/csh?topicname=c_CreatingARecordProducer.html&version=latest
 * @group ServiceCatalog
 */
// biome-ignore lint/suspicious/noRedeclare: function overloads require redeclaration
export function CatalogItemRecordProducer<const V extends VariableTypes>(
    config: CatalogItemRecordProducer<V> & { variables: V }
): CatalogItemRecordProducer<V> & { variables: V }
// biome-ignore lint/suspicious/noRedeclare: function overloads require redeclaration
export function CatalogItemRecordProducer(config: CatalogItemRecordProducer): CatalogItemRecordProducer
export function CatalogItemRecordProducer(config: CatalogItemRecordProducer) {
    return config
}
